"""Regenerate src/bindings.rs from vendor/flecs/flecs.h with bindgen 0.72.x.

Same invocation as hyperion's tools/gen-bindings.sh, minus its nightly-only `#[assume_nonblocking]` marking. No addon
defines are passed, so flecs.h's default (full) addon set is declared; the C build decides what is linked
(hyperion-flecs-c's features). bindgen comes from `nix run nixpkgs#rust-bindgen` unless BINDGEN names one; it needs libclang
and rustfmt.

Usage: python3 vendor/hyperion-ecs-sys/gen-bindings.py
"""

import asyncio
import os
import re
import shlex
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
HEADER = ROOT / "vendor/flecs/flecs.h"
OUT = HERE / "src/bindings.rs"


async def run(*cmd: str, timeout: float) -> str:
    async with asyncio.timeout(timeout):
        p = await asyncio.create_subprocess_exec(*cmd, cwd=ROOT, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
        out, err = await p.communicate()
    if p.returncode:
        tail = "\n".join(err.decode(errors="replace").strip().splitlines()[-20:])
        raise RuntimeError(f"{shlex.join(cmd)}: exit {p.returncode}\n{tail}")
    return out.decode()


async def main() -> None:
    bindgen = shlex.split(os.environ.get("BINDGEN", "nix run nixpkgs#rust-bindgen --"))
    version = (await run(*bindgen, "--version", timeout=600)).strip()
    if not version.startswith("bindgen 0.72."):
        raise RuntimeError(f"want bindgen 0.72.x (the checked-in bindings' version), got {version!r}")
    m = re.search(r'#define FLECS_VERSION_MAJOR (\d+).*?#define FLECS_VERSION_MINOR (\d+).*?#define FLECS_VERSION_PATCH (\d+)', HEADER.read_text(), re.S)
    if not m:
        raise RuntimeError(f"no FLECS_VERSION_* in {HEADER}")
    flecs = ".".join(m.groups())
    rel_header = HEADER.relative_to(ROOT)
    await run(
        *bindgen,
        str(rel_header),
        "--use-core",
        "--ctypes-prefix", "core::ffi",
        "--no-layout-tests",
        "--no-doc-comments",
        "--no-debug", ".*",
        "--default-enum-style", "consts",
        "--no-prepend-enum-name",
        "--allowlist-item", "(ecs|Ecs|ECS|flecs|FLECS).*",
        "--raw-line", f"// @generated by vendor/hyperion-ecs-sys/gen-bindings.py from {rel_header} (flecs v{flecs}). Do not edit.",
        "-o", str(OUT.relative_to(ROOT)),
        "--",
        f"-I{rel_header.parent}",
        "-std=gnu99",
        timeout=600,
    )
    print(f"{OUT.relative_to(ROOT)}: {len(OUT.read_text().splitlines())} lines ({version}, flecs v{flecs})")


asyncio.run(main())
